def classify(apps, schema_editor):
    """Clasifica el catálogo: lo que está en inventario de insumos, en listas de materiales como insumo o en fichas de
    acondicionado como material es INSUMO; lo demás es PRODUCTO. Si un artículo se usaba como las dos cosas, se
    separa: el producto se queda como está y se crea un insumo aparte (código -INS) al que pasan inventario y listas."""
    Product = apps.get_model("mes_core", "Product")
    SupplyStock = apps.get_model("mes_core", "SupplyStock")
    BomLine = apps.get_model("mes_core", "BomLine")
    WorkOrder = apps.get_model("mes_core", "WorkOrder")
    Material = _model(apps, "copacking", "PackagingMaterial")
    Spec = _model(apps, "copacking", "PackagingSpec")

    supply = set(SupplyStock.objects.values_list("product_id", flat=True))
    supply |= set(BomLine.objects.values_list("component_id", flat=True))
    used_as_product = set(WorkOrder.objects.values_list("product_id", flat=True))
    used_as_product |= set(BomLine.objects.values_list("product_id", flat=True))
    if Material is not None:
        supply |= set(Material.objects.values_list("material_id", flat=True))
    if Spec is not None:
        used_as_product |= set(Spec.objects.values_list("product_id", flat=True))

    for p in Product.objects.filter(pk__in=supply - used_as_product):
        p.kind = "insumo"
        p.save(update_fields=["kind"])
    for p in Product.objects.filter(pk__in=supply & used_as_product):
        base = f"{p.sku}-INS"[:40]
        sku, n = base, 1
        while Product.objects.filter(sku=sku).exists():
            n += 1
            sku = f"{base[:36]}-{n}"
        copy = Product.objects.create(sku=sku, name=p.name, unit=p.unit, kind="insumo", active=p.active)
        SupplyStock.objects.filter(product=p).update(product=copy)
        BomLine.objects.filter(component=p).update(component=copy)
        if Material is not None:
            Material.objects.filter(material=p).update(material=copy)


